// Código de cálculo de conversión mantenido intacto
const rows = $input.all();
const stats = {};
for (const row of rows) {
    let fechaRaw = row.json["FECHA"] || row.json["Fecha"];
    let fechaObj = null;
    if (typeof fechaRaw === 'number') {
        fechaObj = new Date((fechaRaw - (25567 + 1)) * 86400 * 1000);
    } else {
        fechaRaw = (fechaRaw || "").toString().trim();
        const matchAnio = fechaRaw.match(/(20\d{2})/);
        if (matchAnio) {
            if (fechaRaw.includes("/")) {
                const partes = fechaRaw.split("/");
                if (partes.length === 3) {
                    const p0 = parseInt(partes[0]);
                    const p1 = parseInt(partes[1]);
                    const p2 = parseInt(partes[2]);
                    if (p2 > 2000) fechaObj = new Date(p2, p1 - 1, p0); 
                    else if (p0 > 2000) fechaObj = new Date(p0, p1 - 1, p2); 
                }
            } else {
                fechaObj = new Date(fechaRaw);
            }
        }
    }
    if (!fechaObj || isNaN(fechaObj.getTime())) continue;
    const year = fechaObj.getFullYear();
    const month = fechaObj.getMonth();
    if (year < 2015) continue; 
    const aseguradoraRaw = (row.json["ASEGURADORA"] || row.json["Aseguradora"] || "").toLowerCase();
    const pagoRaw = (row.json["30/45/60"] || "").toString().toLowerCase(); 
    const lugarRaw = (row.json["LUGAR"] || "").toLowerCase();
    const textoTotal = aseguradoraRaw + " " + lugarRaw + " " + pagoRaw;
    const semestre = month <= 5 ? "S1" : "S2";
    if (!stats[year]) {
        stats[year] = { S1: { mixtos: 0, aseguradora: 0 }, S2: { mixtos: 0, aseguradora: 0 }, Anual: { mixtos: 0, aseguradora: 0 } };
    }
    const esMixto = textoTotal.includes("mixto") || pagoRaw.includes("$") || pagoRaw.includes("+"); 
    const esAseguradora = !esMixto && (textoTotal.includes("aseguradora") || textoTotal.includes("privado"));
    if (esMixto) {
        stats[year][semestre].mixtos++;
        stats[year].Anual.mixtos++;
    } else if (esAseguradora) {
        stats[year][semestre].aseguradora++;
        stats[year].Anual.aseguradora++;
    }
}
const itemsToAppend = [];
function crearFila(nombrePeriodo, datos) {
    const total = datos.mixtos + datos.aseguradora;
    const ratio = total > 0 ? datos.mixtos / total : 0;
    return { "Periodo": nombrePeriodo, " Ratio de conversión": ratio, "Total_Pacientes": total, "Mixtos": datos.mixtos, "total": total, "ratio": ratio, "mixtos": datos.mixtos };
}
const aniosOrdenados = Object.keys(stats).sort();
for (const y of aniosOrdenados) {
    if (stats[y].S1.mixtos + stats[y].S1.aseguradora > 0) itemsToAppend.push(crearFila(`ENE-JUN ${y}`, stats[y].S1));
    if (stats[y].S2.mixtos + stats[y].S2.aseguradora > 0) itemsToAppend.push(crearFila(`JUL-DIC ${y}`, stats[y].S2));
    if (stats[y].Anual.mixtos + stats[y].Anual.aseguradora > 0) itemsToAppend.push(crearFila(`AÑO ${y}`, stats[y].Anual));
}
return itemsToAppend;
